import{_ as a,o as t,c as i,ag as r}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"接入 Redis 并创建数据点","description":"连接 Redis，核对 Key、类型和 TTL，创建点位并分清编辑值、删除 Key 与修改平台映射。","frontmatter":{"title":"接入 Redis 并创建数据点","description":"连接 Redis，核对 Key、类型和 TTL，创建点位并分清编辑值、删除 Key 与修改平台映射。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/redis-datapoints.md","filePath":"zh/使用指南/接入Redis并创建数据点.md"}'),d={name:"zh/guide/redis-datapoints.md"};function s(o,e,h,n,p,_){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="接入-redis-并创建数据点" tabindex="-1">接入 Redis 并创建数据点 <a class="header-anchor" href="#接入-redis-并创建数据点" aria-label="Permalink to &quot;接入 Redis 并创建数据点&quot;">​</a></h1><p>入口：<strong>数据中心 → 接入源 → 新建连接 → Redis</strong>。准备实际服务模式、地址、认证、数据库及 TLS 要求，确认权限与获准操作的 Key 范围。</p><p>先从读取一个已有的练习 Key 开始，不为了生成数据点随意改生产缓存。</p><h2 id="_1-配置连接" tabindex="-1">1. 配置连接 <a class="header-anchor" href="#_1-配置连接" aria-label="Permalink to &quot;1. 配置连接&quot;">​</a></h2><p>按实际服务选择单机、哨兵或集群等页面提供的模式，填写对应地址和凭据，测试后保存。</p><p>服务模式不是可以随意切换的显示选项。一个地址可连接也不能证明全部集群成员、重定向地址和业务权限都正常。</p><h2 id="_2-查看-key-与实际值" tabindex="-1">2. 查看 Key 与实际值 <a class="header-anchor" href="#_2-查看-key-与实际值" aria-label="Permalink to &quot;2. 查看 Key 与实际值&quot;">​</a></h2><p>打开连接的实时数据工作台，按分组或 Key 查找，核对名称、数据类型、TTL 和内容。</p><p>页面提示值已丢失时，检查 Key 是否过期或被外部业务删除。不要把旧的点位定义还在当成外部 Key 仍然有值。</p><p>TTL、外部值类型和平台数据点类型是不同信息，不应为了满足报警数值类型直接覆盖业务原值。</p><h2 id="_3-创建数据点" tabindex="-1">3. 创建数据点 <a class="header-anchor" href="#_3-创建数据点" aria-label="Permalink to &quot;3. 创建数据点&quot;">​</a></h2><p>在对应 Key 使用 **“创建数据点”**或详情里的“创建”，核对生成结果和完整路径，再到“数据点”查看来源。</p><p>分组批量创建前核对范围与数量，避免为大量无关缓存都生成点。是否能够提取为计算所需类型，应按实际值和页面规则确认。</p><h2 id="_4-保存内容可能是真实写入" tabindex="-1">4. 保存内容可能是真实写入 <a class="header-anchor" href="#_4-保存内容可能是真实写入" aria-label="Permalink to &quot;4. 保存内容可能是真实写入&quot;">​</a></h2><p>工作台中的 Key 内容编辑、TTL 修改和 **“保存”**可能直接改变外部 Redis 数据，不只是保存一份平台说明。</p><p>删除 Key、重命名或删除分组也有实际业务影响。先确认授权和依赖；不要把“创建点位”与“创建或覆盖外部值”当成同一操作。</p><h2 id="_5-继续使用" tabindex="-1">5. 继续使用 <a class="header-anchor" href="#_5-继续使用" aria-label="Permalink to &quot;5. 继续使用&quot;">​</a></h2><p>引用真实点路径后核对质量和时间；过期或缺失值不要默认当作正常零值。按需要配置计算、报警和历史，正式运行另外验证实际连接与部署。</p><p>AI 完成后，应同时交付连接名、Key、输出路径，并说明是否实际修改过外部值，不能只说“数据点建好了”。</p><p>下一步：<a href="/induframe-docs/zh/guide/compute-datapoints.html">计算单元</a> · <a href="/induframe-docs/zh/guide/point-alarms.html">报警配置</a> · <a href="/induframe-docs/zh/guide/access-sources.html">接入源总览</a>。</p>',20)])])}const u=a(d,[["render",s]]);export{c as __pageData,u as default};
